import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("Expression must be a string")

    # 1. Tokenize
    raw_tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            raw_tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif c in "+-*/%^!()":
            raw_tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Malformed character: {c}")

    if not raw_tokens:
        raise ValueError("Empty expression")

    # 2. Process tokens for implicit multiplication and invalid adjacencies
    tokens = []
    for idx, tok in enumerate(raw_tokens):
        if idx > 0:
            prev_type = raw_tokens[idx - 1][0]
            curr_type = tok[0]
            if prev_type == "NUM" and curr_type == "NUM":
                raise ValueError("Consecutive numbers separated only by whitespace")
            if prev_type == ")" and curr_type == "NUM":
                raise ValueError("Number directly after closing parenthesis")
            if prev_type == "!" and curr_type == "NUM":
                raise ValueError("Number directly after factorial")
            if curr_type == "(" and prev_type in ("NUM", ")", "!"):
                tokens.append(("*", "*"))
        tokens.append(tok)

    # 3. Arithmetic helper functions
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Division by zero")
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))

    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Remainder by zero")
        sign = -1 if a < 0 else 1
        return sign * (abs(a) % abs(b))

    def power_op(a: int, b: int) -> int:
        if b < 0:
            raise ValueError("Negative exponent")
        return a**b

    def fact_op(a: int) -> int:
        if a < 0:
            raise ValueError("Factorial of negative number")
        return math.factorial(a)

    # 4. Recursive descent parser
    pos = 0
    num_tokens = len(tokens)

    def peek():
        if pos < num_tokens:
            return tokens[pos]
        return None

    def consume(expected_type=None):
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if expected_type is not None and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ("+", "-"):
                op = consume()[0]
                rhs = parse_term()
                if op == "+":
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_u_expr()
        while True:
            tok = peek()
            if tok and tok[0] in ("*", "/", "%"):
                op = consume()[0]
                rhs = parse_u_expr()
                if op == "*":
                    val = val * rhs
                elif op == "/":
                    val = trunc_div(val, rhs)
                elif op == "%":
                    val = trunc_mod(val, rhs)
            else:
                break
        return val

    def parse_u_expr():
        tok = peek()
        if tok and tok[0] == "-":
            consume("-")
            return -parse_u_expr()
        return parse_power()

    def parse_power():
        val = parse_postfix()
        tok = peek()
        if tok and tok[0] == "^":
            consume("^")
            rhs = parse_u_expr()
            val = power_op(val, rhs)
        return val

    def parse_postfix():
        val = parse_primary()
        while True:
            tok = peek()
            if tok and tok[0] == "!":
                consume("!")
                val = fact_op(val)
            else:
                break
        return val

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == "NUM":
            consume("NUM")
            return tok[1]
        elif tok[0] == "(":
            consume("(")
            val = parse_expr()
            consume(")")
            return val
        else:
            raise ValueError(f"Unexpected token: {tok[0]}")

    result = parse_expr()
    if pos < num_tokens:
        raise ValueError(f"Unexpected token at end: {tokens[pos][0]}")
    return result
